def protocol_handlers(protocol_version=None):
    if protocol_version is None:
        return {
            (3, 0): Bolt3,
            (4, 0): Bolt4,
            (4, 1): Bolt41,
            (4, 2): Bolt42,
            (4, 3): Bolt43,
            (4, 4): Bolt44,
        }
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed as a tuple")
        if protocol_version in [(3, 0), (4, 0), (4, 1), (4, 2), (4, 3), (4, 4)]:
            return {protocol_version: globals()["Bolt" + str(protocol_version[0])]}
        else:
            return {}

