def lfu_cache(maxsize=128, typed=False):
    def wrapper(func):
        cache = {}
        use_count = {}
        current_size = 0

        def wrapped(*args, **kwargs):
            nonlocal current_size
            key = args if typed else repr(args)
            if key in cache:
                use_count[key] += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if current_size < maxsize:
                    cache[key] = result
                    use_count[key] = 1
                    current_size += 1
                else:
                    for k, v in sorted(use_count.items(), key=lambda x: x[1]):
                        if v == 1:
                            del cache[k]
                            del use_count[k]
                            current_size -= 1
                            break
                return result
        return wrapped
    return wrapper
