def validate_version_inventories(self, version_dirs):
    # Initialize variables
    root_inventory = None
    version_inventories = {}
    content_digests = {}

    # Iterate over version directories
    for version_dir in version_dirs:
        # Get the inventory for the current version
        inventory = self.get_inventory(version_dir)

        # If the inventory is not present, raise an error
        if inventory is None:
            raise ValueError(f"Inventory not found for version {version_dir}")

        # If this is the first version, set the root inventory
        if root_inventory is None:
            root_inventory = inventory

        # Add the inventory to the version inventories dictionary
        version_inventories[version_dir] = inventory

        # Add the content digests to the content digests dictionary
        for content_digest in inventory.content_digests:
            content_digests[content_digest] = inventory.content_digests[content_digest]

    # Iterate over the version inventories and compare them to the root inventory
    for version_dir, inventory in version_inventories.items():
        # Get the content digests for the current version
        version_content_digests = inventory.content_digests

        # Compare the content digests to the root inventory
        for content_digest in version_content_digests:
            # If the content digest is not present in the root inventory, raise an error
            if content_digest not in root_inventory.content_digests:
                raise ValueError(f"Content digest {content_digest} not found in root inventory for version {version_dir}")

            # If the content digest is present in the root inventory, but the value is different, raise an error
            if root_inventory.content_digests[content_digest] != version_content_digests[content_digest]:
                raise ValueError(f"Content digest {content_digest} has different value in root inventory and version {version_dir}")

    # Return the content digests dictionary
    return content_digests
