def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    for bug_id in bug_ids:
        params['bug_id'] = bug_id
        response = self.bzapi.query(params)
        if response['bugs']:
            bug = response['bugs'][0]
