def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = json.load(f)
                if overrides:
                    config = {**config, **overrides}
                if resolve_env:
                    config = _resolve_env_vars(config)
                configs[config_filename] = config
        except FileNotFoundError:
            errors.append(logging.LogRecord(logging.ERROR, "Configuration file not found: {}".format(config_filename)))
        except json.JSONDecodeError:
            errors.append(logging.LogRecord(logging.ERROR, "Configuration file is not valid JSON: {}".format(config_filename)))
        except Exception as e:
            errors.append(logging.LogRecord(logging.ERROR, "Unexpected error loading configuration file: {}".format(config_filename), exc_info=e))
    return configs, errors
