def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is not __marker:
            return default
        else:
            raise

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    min_count = min(self.values())
    for key, count in self.items():
        if count == min_count:
            break
    self.pop(key)
    return key, min_count

def popitem(self):
    if not self._data:
        raise KeyError("popitem(): dictionary is empty")
    key = None
    for k, _ in self._data.items():
        if key is None or self._data[k] < self._data[key]:
            key = k
    value = self._data.pop(key)
    return key, value

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self.pop(key)
    return key, value

