def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for option_name, option_spec in options_spec.items():
        if 'required_when' in option_spec:
            required_when_spec = option_spec['required_when']
            if isinstance(required_when_spec, str):
                required_when_spec = [required_when_spec]
            for condition in required_when_spec:
                if command_name in condition and args.get(option_name) is None:
                    required_args.append(option_name)
    return required_args
